const inputData = $input.first().json;

// Get previous state from Update Agent 1 Iteration node
const previousState = $('Update Agent 1 Iteration').first().json;

// Get structured output from parser (response.output)
const decision = inputData.response?.output || inputData.output || {
  next_phase: previousState.agent1_phase || 'initializing',
  t0_detected: false,
  beans_added_temp_c: null,
  t0_timestamp_utc: null,
  message: 'No output from agent'
};

// Update system started flags based on phase progression
const roasterStarted = previousState.roaster_started || 
  (decision.next_phase !== 'initializing');
const fcStarted = previousState.fc_detection_started || 
  (decision.next_phase !== 'initializing');

// Check if beans_added_temp_c is a valid number > 90 (handles both string and number)
const tempValue = parseFloat(decision.beans_added_temp_c);
const hasValidBeansTemp = !isNaN(tempValue) && 
  tempValue > 90 &&
  decision.beans_added_temp_c !== null &&
  decision.beans_added_temp_c !== undefined;

return {
  json: {
    agent1_iteration: previousState.agent1_iteration,
    agent1_elapsed_seconds: previousState.agent1_elapsed_seconds,
    agent1_elapsed_display: previousState.agent1_elapsed_display,
    agent1_phase: decision.next_phase,
    agent1_output: decision.message,
    t0_detected: decision.t0_detected || decision.next_phase === 't0_detected' || hasValidBeansTemp,
    beans_added_temp_c: decision.beans_added_temp_c,
    t0_timestamp_utc: decision.t0_timestamp_utc,
    roaster_started: roasterStarted,
    fc_detection_started: fcStarted,
    input: inputData
  }
};

