const inputData = $input.first().json;

// Get previous state from Update Agent 2 Iteration node
const previousState = $('Update Agent 2 Iteration').first().json;

// Get structured output from parser (response.output)
const decision = inputData.response?.output || inputData.output || {
  phase: previousState.agent2_phase || 'pre_first_crack',
  action: 'monitor',
  message: 'No output from agent'
};

return {
  json: {
    agent2_iteration: previousState.agent2_iteration,
    agent2_elapsed_seconds: previousState.agent2_elapsed_seconds,
    agent2_elapsed_display: previousState.agent2_elapsed_display,
    agent2_phase: decision.phase,
    agent2_output: decision.message,
    current_heat: previousState.current_heat,
    current_fan: previousState.current_fan,
    first_crack_detected: decision.phase !== 'pre_first_crack',
    drop_executed: decision.action === 'drop',
    beans_added_temp_c: previousState.beans_added_temp_c,
    t0_timestamp_utc: previousState.t0_timestamp_utc,
    agent1_output: previousState.agent1_output
  }
};
